cd /home/runner/work/PlayGround/PlayGround && cat > /tmp/mech.cjs << 'EOF'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
  const browser = await chromium.launch({headless:true});
  const page = await browser.newPage();
  const errors=[]; const cons=[];
  page.on('pageerror', e=>errors.push(e.message));
  page.on('console', m=>cons.push(m.text()));
  await page.goto('http://localhost:3333/', {waitUntil:'load'});
  await page.waitForTimeout(400);
  await page.evaluate(()=>window.game.start());
  await page.waitForTimeout(600);
  // get nearest creature coords, click to strike
  const gstate = await page.evaluate(()=>{
    const g=window.game;
    let target=null, bd=1e9;
    for(const c of g.creatures){ if(c.hp>0){ const d=Math.hypot(c.x-g.player.x,c.y-g.player.y); if(d<bd){bd=d;target=c;} } }
    return target?{cx:target.x,g.camera.x,g.camera.y}:null;
  });
  console.log('target world:', JSON.stringify(gstate));
  // screen position = world - camera + canvas center
  const screenX = 640 + (gstate.cx - gstate.g.camera.x);
  const screenY = 360 + (gstate.cy - gstate.g.camera.y);
  await page.mouse.click(screenX, screenY);
  await page.waitForTimeout(300);
  await page.screenshot({path:'screenshots/mech1.jpg',type:'jpeg',quality:90});
  // throw a ball (right click)
  await page.mouse.click(screenX, screenY, {button:'right'});
  await page.waitForTimeout(900); // catch animation
  const catchState = await page.evaluate(()=>({ catchOpen: !!document.getElementById('catch').classList.contains('hidden')===false, balls: window.game.ballsCount, party: window.game.party.length }));
  console.log('catchState:', JSON.stringify(catchState));
  await page.screenshot({path:'screenshots/mech2.jpg',type:'jpeg',quality:90});
  console.log('ERRORS:', JSON.stringify(errors));
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1);});
EOF
